import React, { useEffect, useRef, useState } from 'react';
import { getAdminTasks, getAdminUsers, getAssignableUsers, getProjects, getTasks } from './api';
import './analytics.css';

function Analytics({ stats = { total: 0, completed: 0, remaining: 0 }, userRole = 'Admin' }) {
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');
  const [showFilterDropdown, setShowFilterDropdown] = useState(false);
  const [projects, setProjects] = useState([]);
  const [tasks, setTasks] = useState([]);
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [selectedEmployees, setSelectedEmployees] = useState({});
  const [activeActionMenuId, setActiveActionMenuId] = useState(null);

  const actionMenuRef = useRef(null);

  useEffect(() => {
    function handleClickOutside(event) {
      if (actionMenuRef.current && !actionMenuRef.current.contains(event.target)) {
        setActiveActionMenuId(null);
      }
    }
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    let isMounted = true;
    setLoading(true);
    Promise.all([
      getProjects().catch(() => ({ data: [] })),
      (userRole === 'Admin' ? getAdminTasks() : getTasks()).catch(() => ({ data: [] })),
      (userRole === 'Admin' ? getAdminUsers() : getAssignableUsers()).catch(() => ({ data: [] })),
    ])
      .then(([projRes, taskRes, userRes]) => {
        if (!isMounted) return;
        setProjects(Array.isArray(projRes?.data) ? projRes.data : []);
        setTasks(Array.isArray(taskRes?.data) ? taskRes.data : []);
        setUsers(Array.isArray(userRes?.data) ? userRes.data : []);
      })
      .catch((err) => {
        if (isMounted) setError(err.message);
      })
      .finally(() => {
        if (isMounted) setLoading(false);
      });

    return () => {
      isMounted = false;
    };
  }, [userRole]);

  // Dynamic Metrics Calculation
  const totalProjectCount = projects.length || (tasks.length ? Math.ceil(tasks.length / 3) : 0);
  const completedTaskCount = tasks.filter((t) => t.status === 'completed' || t.completed).length;
  const inProgressTaskCount = tasks.filter((t) => t.status === 'in-progress' || t.status === 'in_progress').length;
  const pendingTaskCount = tasks.filter((t) => t.status === 'pending' || !t.status).length;
  const totalTaskCount = tasks.length;

  const projectProgressPct = totalTaskCount > 0 ? Math.round((completedTaskCount / totalTaskCount) * 100) : 0;

  // Calculate Monthly Task Bar heights
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  const monthCounts = new Array(12).fill(0);
  tasks.forEach((t) => {
    const d = t.createdAt ? new Date(t.createdAt) : new Date();
    const m = d.getMonth();
    if (m >= 0 && m < 12) monthCounts[m]++;
  });
  const maxMonthCount = Math.max(...monthCounts, 1);
  const monthlyBars = months.map((m, idx) => {
    const count = monthCounts[idx];
    const pct = Math.max(15, Math.min(100, Math.round((count / maxMonthCount) * 90)));
    return {
      month: m,
      height: `${pct}%`,
      active: idx === new Date().getMonth(),
    };
  });

  // Team collaboration list built from real users
  const teamCollab = users.length > 0 ? users.slice(0, 5).map((u) => {
    const uTasks = tasks.filter((t) => String(t.assignedUser?._id || t.assignedUser) === String(u._id));
    const uCompleted = uTasks.filter((t) => t.status === 'completed').length;
    const uInProgress = uTasks.filter((t) => t.status === 'in-progress').length;
    let statusLabel = 'Active';
    let badgeClass = 'pill-status-complete';
    if (uTasks.length > 0 && uCompleted === uTasks.length) {
      statusLabel = 'Complete';
      badgeClass = 'pill-status-complete';
    } else if (uInProgress > 0) {
      statusLabel = 'In progress';
      badgeClass = 'pill-status-in-progress';
    } else if (uTasks.length > 0) {
      statusLabel = 'Pending';
      badgeClass = 'pill-status-pending';
    }
    return {
      name: u.fullname || u.username || 'Team Member',
      email: u.email || `${(u.username || 'user').toLowerCase()}@workspace.com`,
      status: statusLabel,
      badge: badgeClass,
    };
  }) : [
    { name: 'Steve Wuckert', email: 'Steve53@gmail.com', status: 'Complete', badge: 'pill-status-complete' },
    { name: 'Carlton Little', email: 'carlton.l@gmail.com', status: 'In progress', badge: 'pill-status-in-progress' },
    { name: 'Ricky Asper', email: 'ricky67@yahoo.com', status: 'Pending', badge: 'pill-status-pending' },
  ];

  // Employee list built from real users
  const employeeData = users.length > 0 ? users.map((u, idx) => ({
    id: `#EMP-${101 + idx}`,
    _id: u._id,
    name: u.fullname || u.username || 'Employee',
    email: u.email || 'employee@workspace.com',
    dept: u.role || 'Member',
    status: 'Active',
  })) : [
    { id: '#EMP-101', _id: '1', name: 'Steve Wuckert', email: 'Steve53@gmail.com', dept: 'Development', status: 'Active' },
    { id: '#EMP-102', _id: '2', name: 'Carlton Little', email: 'carlton.l@gmail.com', dept: 'Design', status: 'Active' },
    { id: '#EMP-103', _id: '3', name: 'Ricky Asper', email: 'ricky67@yahoo.com', dept: 'QA Testing', status: 'Active' },
  ];

  const filteredEmployees = employeeData.filter((e) => {
    const matchesSearch = !search || `${e.name} ${e.email} ${e.dept}`.toLowerCase().includes(search.toLowerCase());
    const matchesFilter = statusFilter === 'All' || e.status === statusFilter;
    return matchesSearch && matchesFilter;
  });

  const toggleSelectAll = (e) => {
    const checked = e.target.checked;
    const newSelected = {};
    if (checked) {
      filteredEmployees.forEach((emp) => {
        newSelected[emp.id] = true;
      });
    }
    setSelectedEmployees(newSelected);
  };

  const toggleSelectRow = (id) => {
    setSelectedEmployees((prev) => ({
      ...prev,
      [id]: !prev[id],
    }));
  };

  // Helper function to generate and download a clean, styled HTML report
  const downloadUserReport = (emp) => {
    const empTasks = tasks.filter((t) => String(t.assignedUser?._id || t.assignedUser) === String(emp._id));
    const completed = empTasks.filter((t) => t.status === 'completed' || t.completed).length;
    const inProgress = empTasks.filter((t) => t.status === 'in-progress' || t.status === 'in_progress').length;
    const pending = empTasks.filter((t) => t.status === 'pending' || !t.status).length;

    const taskRows = empTasks.length > 0
      ? empTasks.map((t, i) => `
          <tr>
            <td>${i + 1}</td>
            <td><strong>${t.title || 'Untitled'}</strong></td>
            <td><span class="badge status-${(t.status || 'pending').toLowerCase()}">${t.status || 'pending'}</span></td>
          </tr>
        `).join('')
      : `<tr><td colspan="3" class="empty">No tasks currently assigned.</td></tr>`;

    const htmlContent = `
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Employee Report - ${emp.name}</title>
  <style>
    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
      background-color: #f8fafc;
      color: #1e293b;
      margin: 0;
      padding: 40px 20px;
      display: flex;
      justify-content: center;
    }
    .report-card {
      background: #ffffff;
      width: 100%;
      max-width: 680px;
      padding: 36px;
      border-radius: 12px;
      box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.05), 0 8px 10px -6px rgba(0, 0, 0, 0.01);
      border: 1px solid #e2e8f0;
    }
    .header {
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
      border-bottom: 2px solid #f1f5f9;
      padding-bottom: 20px;
      margin-bottom: 24px;
    }
    .brand {
      font-size: 20px;
      font-weight: 700;
      color: #4f46e5;
    }
    .title {
      font-size: 14px;
      color: #64748b;
      text-transform: uppercase;
      letter-spacing: 0.5px;
      margin-top: 4px;
    }
    .date-badge {
      font-size: 12px;
      background: #f1f5f9;
      padding: 6px 12px;
      border-radius: 20px;
      color: #475569;
      font-weight: 500;
    }
    .emp-info {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 16px;
      background: #f8fafc;
      padding: 20px;
      border-radius: 8px;
      margin-bottom: 28px;
    }
    .info-item label {
      display: block;
      font-size: 11px;
      text-transform: uppercase;
      color: #94a3b8;
      font-weight: 600;
      margin-bottom: 2px;
    }
    .info-item span {
      font-size: 14px;
      font-weight: 600;
      color: #0f172a;
    }
    .stats-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 12px;
      margin-bottom: 28px;
    }
    .stat-box {
      background: #ffffff;
      border: 1px solid #e2e8f0;
      padding: 14px;
      border-radius: 8px;
      text-align: center;
    }
    .stat-box strong {
      display: block;
      font-size: 20px;
      color: #0f172a;
      margin-bottom: 2px;
    }
    .stat-box span {
      font-size: 11px;
      color: #64748b;
      font-weight: 500;
    }
    .section-title {
      font-size: 14px;
      font-weight: 700;
      color: #334155;
      margin-bottom: 12px;
      text-transform: uppercase;
      letter-spacing: 0.5px;
    }
    table {
      width: 100%;
      border-collapse: collapse;
    }
    th {
      text-align: left;
      font-size: 12px;
      color: #64748b;
      padding: 10px 12px;
      border-bottom: 2px solid #f1f5f9;
      background: #f8fafc;
    }
    td {
      padding: 12px;
      font-size: 13px;
      border-bottom: 1px solid #f1f5f9;
    }
    .badge {
      display: inline-block;
      padding: 4px 10px;
      border-radius: 12px;
      font-size: 11px;
      font-weight: 600;
      text-transform: capitalize;
    }
    .status-completed { background: #dcfce7; color: #166534; }
    .status-in-progress { background: #e0e7ff; color: #3730a3; }
    .status-pending { background: #fef3c7; color: #92400e; }
    .empty { text-align: center; color: #94a3b8; padding: 20px; }
  </style>
</head>
<body>
  <div class="report-card">
    <div class="header">
      <div>
        <div class="brand">TaskFlow Workspace</div>
        <div class="title">Employee Performance Report</div>
      </div>
      <div class="date-badge">Generated: ${new Date().toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' })}</div>
    </div>

    <div class="emp-info">
      <div class="info-item"><label>Full Name</label><span>${emp.name}</span></div>
      <div class="info-item"><label>Employee ID</label><span>${emp.id}</span></div>
      <div class="info-item"><label>Email Address</label><span>${emp.email}</span></div>
      <div class="info-item"><label>Department / Role</label><span>${emp.dept}</span></div>
    </div>

    <div class="section-title">Task Overview</div>
    <div class="stats-grid">
      <div class="stat-box"><strong>${empTasks.length}</strong><span>Total Assigned</span></div>
      <div class="stat-box"><strong>${completed}</strong><span>Completed</span></div>
      <div class="stat-box"><strong>${inProgress}</strong><span>In Progress</span></div>
      <div class="stat-box"><strong>${pending}</strong><span>Pending</span></div>
    </div>

    <div class="section-title">Task Breakdown</div>
    <table>
      <thead>
        <tr>
          <th style="width: 40px;">#</th>
          <th>Task Title</th>
          <th style="width: 120px;">Status</th>
        </tr>
      </thead>
      <tbody>
        ${taskRows}
      </tbody>
    </table>
  </div>
</body>
</html>
`;

    const blob = new Blob([htmlContent.trim()], { type: 'text/html;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${emp.name.replace(/\s+/g, '_')}_Report.html`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="analytics-page">
      <div className="projects-heading">
        <div>
          <p className="dashboard-label">WORKSPACE PERFORMANCE</p>
          <h2>{userRole === 'Admin' ? 'Project Analytics & Overview' : 'Personal Performance'}</h2>
          <p>Track team progress, employee data, and productivity metrics live from backend.</p>
        </div>
      </div>

      {error && <div className="project-error" role="alert">{error}</div>}

      {/* TOP ROW: METRIC CARDS & MONTHLY BAR CHART */}
      <div className="analytics-grid">
        <div className="analytics-cards-grid">
          <div className="analytics-card">
            <div className="analytics-card-header">
              <span>Total Projects</span>
              <button type="button" aria-label="Options" className="icon-btn">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/><circle cx="5" cy="12" r="1"/></svg>
              </button>
            </div>
            <strong>{loading ? '...' : totalProjectCount}</strong>
            <small className="trend-label">
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><polyline points="22 7 13.5 15.5 8.5 10.5 2 17"/><polyline points="16 7 22 7 22 13"/></svg> Workspace total projects
            </small>
          </div>

          <div className="analytics-card">
            <div className="analytics-card-header">
              <span>Completed Tasks</span>
              <button type="button" aria-label="Options" className="icon-btn">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/><circle cx="5" cy="12" r="1"/></svg>
              </button>
            </div>
            <strong>{loading ? '...' : completedTaskCount}</strong>
            <small className="trend-label">
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><polyline points="22 7 13.5 15.5 8.5 10.5 2 17"/><polyline points="16 7 22 7 22 13"/></svg> Finished tasks count
            </small>
          </div>

          <div className="analytics-card">
            <div className="analytics-card-header">
              <span>Running Tasks</span>
              <button type="button" aria-label="Options" className="icon-btn">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/><circle cx="5" cy="12" r="1"/></svg>
              </button>
            </div>
            <strong>{loading ? '...' : inProgressTaskCount}</strong>
            <small className="trend-label">
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><polyline points="22 7 13.5 15.5 8.5 10.5 2 17"/><polyline points="16 7 22 7 22 13"/></svg> In-progress active tasks
            </small>
          </div>

          <div className="analytics-card">
            <div className="analytics-card-header">
              <span>Pending Tasks</span>
              <button type="button" aria-label="Options" className="icon-btn">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/><circle cx="5" cy="12" r="1"/></svg>
              </button>
            </div>
            <strong>{loading ? '...' : pendingTaskCount}</strong>
            <small className="trend-label">
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><polyline points="22 7 13.5 15.5 8.5 10.5 2 17"/><polyline points="16 7 22 7 22 13"/></svg> Waiting for action
            </small>
          </div>
        </div>

        <section className="panel">
          <div className="panel-heading">
            <h2>Project Analytics</h2>
            <button className="more-button" type="button" aria-label="More option">⋮</button>
          </div>
          <div className="bar-chart-container">
            {monthlyBars.map((bar) => (
              <div className={`bar-column ${bar.active ? 'active' : ''}`} key={bar.month}>
                <div className="bar-fill" style={{ height: bar.height }} />
                <span className="bar-label">{bar.month}</span>
              </div>
            ))}
          </div>
        </section>
      </div>

      {/* MIDDLE ROW: TEAM COLLABORATION & PROJECT PROGRESS */}
      <div className="analytics-grid" style={{ marginTop: '16px' }}>
        <section className="panel">
          <div className="panel-heading">
            <h2>Team Collaboration</h2>
            <button className="more-button" type="button" aria-label="Add user">+</button>
          </div>
          <div className="team-collab-list">
            {teamCollab.map((member) => (
              <div className="team-collab-item" key={member.email}>
                <div className="team-collab-user">
                  <div className="team-avatar">{member.name.charAt(0).toUpperCase()}</div>
                  <div>
                    <strong>{member.name}</strong>
                    <small>{member.email}</small>
                  </div>
                </div>
                <span className={`pill-badge ${member.badge}`}>{member.status}</span>
              </div>
            ))}
          </div>
        </section>

        <section className="panel" style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
          <div className="panel-heading" style={{ width: '100%' }}>
            <h2>Project Progress</h2>
            <button className="more-button" type="button" aria-label="Add project">+</button>
          </div>

          <div className="working-status-ring-container" style={{ margin: 'auto' }}>
            <div
              className="working-status-ring"
              style={{
                width: '160px',
                height: '160px',
                background: `conic-gradient(#7c3aed 0% ${projectProgressPct}%, #e2e8f0 ${projectProgressPct}% 100%)`,
              }}
            >
              <div className="working-status-center" style={{ width: '120px', height: '120px' }}>
                <strong style={{ fontSize: '1.4rem' }}>{projectProgressPct}%</strong>
                <span style={{ fontSize: '0.74rem' }}>Progress</span>
              </div>
            </div>
          </div>

          <div className="priority-legend" style={{ flexDirection: 'row', gap: '16px', marginTop: '14px' }}>
            <span><i style={{ background: '#7c3aed' }} /> Completed ({completedTaskCount})</span>
            <span><i style={{ background: '#cbd5e1' }} /> Remaining ({totalTaskCount - completedTaskCount})</span>
          </div>
        </section>
      </div>

      {/* BOTTOM ROW: TOTAL EMPLOYEE DATA TABLE */}
      <section className="panel" style={{ marginTop: '16px', overflow: 'visible' }}>
        <div className="panel-heading" style={{ flexWrap: 'wrap', gap: '12px' }}>
          <div>
            <h2>Total Employees: {employeeData.length}</h2>
          </div>

          <div style={{ display: 'flex', gap: '8px', alignItems: 'center', flexWrap: 'wrap', position: 'relative' }}>
            <div className="search-box" style={{ maxWidth: '220px' }}>
              <span style={{ display: 'flex', alignItems: 'center' }}>
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
              </span>
              <input
                type="text"
                placeholder="Search employee..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
              />
            </div>

            <button className="more-button" type="button" onClick={() => window.print()} style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg>
              Report
            </button>

            <button
              className="more-button"
              type="button"
              onClick={() => setShowFilterDropdown((prev) => !prev)}
              style={{ display: 'flex', alignItems: 'center', gap: '4px', background: statusFilter !== 'All' ? '#e2e8f0' : undefined }}
            >
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3"/></svg>
              Filter {statusFilter !== 'All' ? `(${statusFilter})` : ''}
            </button>

            {showFilterDropdown && (
              <div className="panel-more-menu" style={{ position: 'absolute', right: 0, top: '100%', zIndex: 10, marginTop: '4px' }}>
                <button type="button" onClick={() => { setStatusFilter('All'); setShowFilterDropdown(false); }}>All Statuses</button>
                <button type="button" onClick={() => { setStatusFilter('Active'); setShowFilterDropdown(false); }}>Active Only</button>
              </div>
            )}
          </div>
        </div>

        <div className="employee-table-wrapper" style={{ overflow: 'visible' }}>
          <table className="employee-table">
            <thead>
              <tr>

                <th>ID</th>
                <th>Name</th>
                <th>Email</th>
                <th>Department / Role</th>
                <th>Status</th>
                <th>Action</th>
              </tr>
            </thead>
            <tbody>
              {filteredEmployees.map((e) => (
                <tr key={e.id}>
                  <td>
                    <input
                      type="checkbox"
                      aria-label={`Select ${e.name}`}
                      checked={Boolean(selectedEmployees[e.id])}
                      onChange={() => toggleSelectRow(e.id)}
                    />
                  </td>
                  <td><strong>{e.id}</strong></td>
                  <td>{e.name}</td>
                  <td>{e.email}</td>
                  <td>{e.dept}</td>
                  <td><span className="pill-badge pill-status-complete">{e.status}</span></td>
                  <td style={{ position: 'relative' }}>
                    <button
                      type="button"
                      aria-label="Options"
                      className="more-button"
                      onClick={() => setActiveActionMenuId((prev) => (prev === e.id ? null : e.id))}
                      style={{ cursor: 'pointer' }}
                    >
                      <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                        <circle cx="12" cy="12" r="1"/>
                        <circle cx="19" cy="12" r="1"/>
                        <circle cx="5" cy="12" r="1"/>
                      </svg>
                    </button>

                    {activeActionMenuId === e.id && (
                      <div
                        ref={actionMenuRef}
                        className="panel-more-menu"
                        style={{
                          position: 'absolute',
                          right: '10px',
                          top: '80%',
                          zIndex: 100,
                          minWidth: '140px',
                          backgroundColor: '#ffffff',
                          boxShadow: '0 4px 12px rgba(0,0,0,0.15)',
                          borderRadius: '8px',
                          padding: '4px 0',
                        }}
                      >
                        <button
                          type="button"
                          onClick={() => {
                            alert(`Employee Details:\nName: ${e.name}\nEmail: ${e.email}\nRole: ${e.dept}`);
                            setActiveActionMenuId(null);
                          }}
                        >
                          View Details
                        </button>
                        <button
                          type="button"
                          onClick={() => {
                            downloadUserReport(e);
                            setActiveActionMenuId(null);
                          }}
                        >
                          Download Report
                        </button>
                      </div>
                    )}
                  </td>
                </tr>
              ))}
              {filteredEmployees.length === 0 && (
                <tr>
                  <td colSpan="7" style={{ textAlign: 'center', padding: '16px', color: '#94a3b8' }}>
                    No matching employees found.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </section>
    </div>
  );
}

export default Analytics;che
